// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/users", wrapper.SearchUsers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/users", wrapper.RegisterUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/users/{id}", wrapper.GetUserInfo)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/sessions", wrapper.LoginSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/tokens", wrapper.RefreshToken)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/sessions/{id}", wrapper.InvalidateSession)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/profile", wrapper.EditProfile)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/chats", wrapper.GetChats)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/chats", wrapper.CreateChat)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/chats/{id}", wrapper.DeleteChat)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/chats/{id}", wrapper.GetChatInfo)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/chats/{id}/messages", wrapper.GetMessages)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/chats/{id}/messages", wrapper.SendMessage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/chats/{id}/members", wrapper.GetChatMembers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/chats/{id}/members", wrapper.AddChatMember)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/chats/{id}/members/{userId}", wrapper.DeleteChatMember)

	return m
}

